CREATE OR REPLACE FUNCTION public.icash_begin_customer_phone_call(p_actor uuid, p_account uuid, p_screening uuid, p_recipient text, p_callback text, p_id uuid, p_sender text, p_provider_account text, p_nonce_hash text, p_quote jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare old public.icash_customer_phone_calls;r uuid;costs jsonb;part record;total bigint:=0;hold bigint;cap bigint;reason text;manual jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_actor for update;
 if not found then raise exception 'Account owner required';end if;
 select * into old from public.icash_customer_phone_calls where id=p_id;
 if found then
  if old.account_id<>p_account or old.actor_id<>p_actor or old.screening_id<>p_screening or old.callback_phone<>p_callback or old.recipient_phone<>p_recipient then raise exception 'Call key conflict';end if;
  return jsonb_build_object('created',false,'call',to_jsonb(old));
 end if;
 if (case when p_quote->>'connectionType'='browser' then p_callback !~ '^client:icash_[a-f0-9]{64}$' else p_callback !~ '^\+1[2-9][0-9]{9}$' end) or p_callback=p_recipient or p_callback=p_sender or p_recipient=p_sender then return jsonb_build_object('error','Enter your own phone number, different from the seller and business number.');end if;
 if p_provider_account !~ '^AC[a-fA-F0-9]{32}$' or p_nonce_hash !~ '^[a-f0-9]{64}$' then raise exception 'Provider binding required';end if;
 perform pg_advisory_xact_lock(818,1);
 if p_sender is null or p_sender is distinct from public.icash_customer_call_sender(p_account,p_screening,p_recipient) then return jsonb_build_object('error','Your business calling number is unavailable. Please try again.');end if;
 if exists(select 1 from public.icash_customer_phone_calls where account_id=p_account and ended_at is null) then return jsonb_build_object('error','A previous call is still active or being checked.');end if;
 if (select count(*) from public.icash_customer_phone_calls where (callback_phone=p_callback or account_id=p_account) and created_at>now()-interval '1 hour')>=5 then return jsonb_build_object('error','Too many call attempts. Try again later.');end if;
 reason:=public.icash_manual_contact_reason(p_account,p_screening,p_recipient,'voice');if reason is not null then return jsonb_build_object('error',reason);end if;
 if p_quote->>'currency' is distinct from 'USD' or p_quote->>'country' is distinct from 'US' or p_quote->>'from' is distinct from p_sender or p_quote->>'callback' is distinct from p_callback or p_quote->>'recipient' is distinct from p_recipient or p_quote->>'checkedAt' is null or p_quote->>'receiptHash' is null or p_quote->>'receiptHash' !~ '^[a-f0-9]{64}$' or (p_quote->>'checkedAt')::timestamptz<now()-interval '2 minutes' or (p_quote->>'checkedAt')::timestamptz>now()+interval '5 seconds' then raise exception 'Current bound pricing required';end if;
 if jsonb_typeof(p_quote->'callbackMicrosPerMinute') is distinct from 'number' or jsonb_typeof(p_quote->'recipientMicrosPerMinute') is distinct from 'number' or (p_quote->>'callbackMicrosPerMinute')::numeric not between 1 and 100000 or (p_quote->>'recipientMicrosPerMinute')::numeric not between 1 and 100000 then raise exception 'Call price unavailable';end if;
 if p_quote->>'connectionType'='browser' and (p_quote->>'recordingPolicy' is distinct from 'customer-phone-recorded-v1' or (p_quote->>'callbackMicrosPerMinute')::numeric<>4000) then raise exception 'Browser recording and rate required';end if;
 -- Retain approved platform allocations; record both legs once for new clients.
 if p_quote->>'recordingPolicy' is not null and p_quote->>'recordingPolicy'<>'customer-phone-recorded-v1' then raise exception 'Unknown recording policy';end if;
 select r.costs_micros into costs from public.icash_operation_rates r join public.icash_voice_configs c on c.seller_rate_id=r.id where c.account_id=p_account and c.enabled and r.operation='seller_call' and r.enabled and r.expires_at>now() order by r.verified_at desc limit 1;
 if costs is null then raise exception 'Operating cost review required';end if;
 costs:=costs||jsonb_build_object('twilio',ceil(((p_quote->>'callbackMicrosPerMinute')::numeric+(p_quote->>'recipientMicrosPerMinute')::numeric)*10),'elevenlabs',0,'llm',0,'other',case when p_quote->>'recordingPolicy'='customer-phone-recorded-v1' then 33000 else 0 end,'messaging',0,'email',0,'dealmachine',0,'title_and_signing',0,'acquisition',0);
 select sum(value::text::bigint) into total from jsonb_each(costs);
 hold:=ceil(total::numeric*2*1.2/10000);
 if hold not between 1 and 1000 or not exists(select 1 from public.icash_operating_budget where id=1 and enabled and standard_cost_multiplier=2 and elevenlabs_cost_multiplier=2) then raise exception '2x calling pricing required';end if;
 insert into public.icash_operation_rates(operation,version,charge_cents,costs_micros,buffer_bps,evidence_ref,verified_at,expires_at,enabled,voice_max_duration_seconds)
 values('customer_phone_call',case when p_quote->>'recordingPolicy'='customer-phone-recorded-v1' then 'customer-phone-recorded-2x-v1:' else 'customer-phone-2x-v1:' end||p_id,hold,costs,2000,'Live Twilio number pricing: '||p_quote::text||'; 600s each leg; existing approved platform allocations are estimates; no AI. Recording when enabled: estimate 2500 micros/minute capture plus 500 micros/minute for 30-day storage; 11-minute bounded allowance.',now(),now()+interval '15 minutes',true,600) returning id into r;
 insert into public.icash_customer_phone_calls(id,account_id,actor_id,screening_id,callback_phone,recipient_phone,business_phone,provider_account_sid,nonce_hash,operation_key,rate_id,recording_required,recording_state,connection_type)
 values(p_id,p_account,p_actor,p_screening,p_callback,p_recipient,p_sender,p_provider_account,p_nonce_hash,'customer-phone:'||p_id,r,coalesce(p_quote->>'recordingPolicy'='customer-phone-recorded-v1',false),case when p_quote->>'recordingPolicy'='customer-phone-recorded-v1' then 'pending' else 'unrequested' end,case when p_quote->>'connectionType'='browser' then 'browser' else 'phone' end);
 perform public.icash_reserve_operation(p_account,'customer-phone:'||p_id,r,now()+interval '2 minutes');
 if not public.icash_claim_operation('customer-phone:'||p_id) then raise exception 'Call spending not available';end if;
 manual:=public.icash_start_manual_call(p_actor,p_account,p_screening,p_recipient);
 if manual->>'error' is not null then raise exception 'Contact state changed';end if;
 select * into old from public.icash_customer_phone_calls where id=p_id;
 return jsonb_build_object('created',true,'call',to_jsonb(old),'holdCents',hold);
end $function$

CREATE OR REPLACE FUNCTION public.icash_owner_account_view(p_actor uuid, p_session uuid, p_view uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v icash_private.owner_account_views;account jsonb;
begin
 if p_actor is distinct from '592171a0-2bb9-484e-8c9a-dd5d2b43b5f7'::uuid
  or not exists(select 1 from auth.sessions where id=p_session and user_id=p_actor and (not_after is null or not_after>now())) then raise exception 'Owner session required' using errcode='42501';end if;
 select r.* into v from icash_private.owner_account_views r join public.icash_accounts a on a.id=r.account_id and a.owner_user_id=r.target_user_id
 where r.id=p_view and r.actor_id=p_actor and r.actor_session_id=p_session and r.ended_at is null and r.expires_at>now();
 if not found then return null;end if;
 account:=public.icash_owner_accounts(p_actor,'funded','',1,v.account_id)->'accounts'->0;
 if account is null then return null;end if;
 return jsonb_build_object('id',v.id,'expiresAt',v.expires_at,'account',account);
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_manual_text(p_actor uuid, p_account uuid, p_screening uuid, p_phone text, p_terms jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare d public.icash_deal_files;t public.icash_text_threads;sender_phone text;rate uuid;reason text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_actor for update;
 if not found then raise exception 'Account owner required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_phone,74));
 if not exists(select 1 from public.icash_manual_contacts(p_account,p_screening) where phone=p_phone and not blocked and phone_type<>'landline') then return jsonb_build_object('error','This number is unavailable for texting.');end if;
 select * into d from public.icash_deal_files where account_id=p_account and screening_id=p_screening;
 if d.id is null then
  insert into public.icash_deal_files(account_id,screening_id,terms) values(p_account,p_screening,p_terms) on conflict(account_id,screening_id) do nothing;
  select * into d from public.icash_deal_files where account_id=p_account and screening_id=p_screening;
 end if;
 select * into t from public.icash_text_threads where retired_at is null and account_id=p_account and deal_id=d.id and recipient=p_phone order by id limit 1;
 if t.id is not null then return jsonb_build_object('dealId',d.id,'threadId',t.id);end if;
 -- Existing conversations retain their sender. New conversations use one configured business sender.
 sender_phone:=public.icash_property_text_sender(p_account,d.id,p_phone);
 if sender_phone is null then return jsonb_build_object('error','No unused texting number is available for this contact. Review the existing conversation or add a number.');end if;
 perform public.icash_retire_expired_practice_threads(p_account,sender_phone,p_phone);
 if exists(select 1 from public.icash_text_threads where retired_at is null and sender=sender_phone and recipient=p_phone) then return jsonb_build_object('error','This number already has a conversation on another property. Open that conversation.');end if;
 select id into rate from public.icash_operation_rates where operation='sms_send' and enabled and expires_at>now() order by verified_at desc,id limit 1;
 insert into public.icash_text_threads(sender_pool_assigned,account_id,deal_id,sender,recipient,sms_rate_id,paused,ai_mode,manual_only) values(true,p_account,d.id,sender_phone,p_phone,rate,true,'off',true) returning * into t;
 return jsonb_build_object('dealId',d.id,'threadId',t.id);
end $function$

CREATE OR REPLACE FUNCTION public.icash_queue_customer_text(p_actor uuid, p_account uuid, p_thread uuid, p_key uuid, p_body text, p_assets uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare screening uuid;message uuid;prior public.icash_text_messages;reason text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_actor for update;
 if not found then raise exception 'Account owner required';end if;
 select d.screening_id into screening from public.icash_text_threads t join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id
 where t.id=p_thread and t.account_id=p_account and d.stage not in ('closed','cancelled');
 if screening is null then raise exception 'Lead conversation unavailable';end if;
 select * into prior from public.icash_text_messages where request_key=p_key;
 if found and (prior.account_id<>p_account or prior.customer_author_id is distinct from p_actor) then raise exception 'Message key conflict';end if;
 if prior.id is null then
 reason:=public.icash_manual_text_reason(p_account,p_thread);if reason is not null then return jsonb_build_object('error',reason);end if;
 end if;
 message:=public.icash_queue_text(p_account,p_thread,p_key,p_body,p_assets);
 if prior.id is null then
  update public.icash_text_messages set customer_author_id=p_actor where id=message and account_id=p_account;
  perform public.icash_set_work_control(p_actor,p_account,'takeover',screening);
 end if;
 return jsonb_build_object('id',message,'manual',exists(select 1 from public.icash_property_controls c join public.icash_screening_jobs s on s.account_id=c.account_id and s.snapshot->>'propertyId'=c.property_id where s.id=screening and s.account_id=p_account and c.manual));
end $function$

CREATE OR REPLACE FUNCTION public.icash_start_manual_call(p_actor uuid, p_account uuid, p_screening uuid, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare reason text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_actor for update;
 if not found then raise exception 'Account owner required';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_phone,74));
 reason:=public.icash_manual_contact_reason(p_account,p_screening,p_phone,'voice');
 if reason is not null then return jsonb_build_object('error',reason);end if;
 perform public.icash_set_work_control(p_actor,p_account,'takeover',p_screening);
 insert into public.icash_manual_call_attempts(account_id,screening_id,phone,actor_id) values(p_account,p_screening,p_phone,p_actor);
 return jsonb_build_object('manual',true,'dialUrl','tel:'||p_phone);
end $function$

CREATE OR REPLACE FUNCTION public.icash_set_work_control_before_sms_intake(p_user uuid, p_account uuid, p_action text, p_screening uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prop text;
begin
 perform 1 from public.icash_accounts where id=p_account and owner_user_id=p_user for update;
 if not found then raise exception 'Account ownership required';end if;
 if p_action in ('pause','resume') then
 update public.icash_accounts set bot_paused=(p_action='pause') where id=p_account;
 elsif p_action in ('takeover','return_to_bot') then
 select snapshot->>'propertyId' into prop from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if prop is null then raise exception 'Property missing';end if;
 insert into public.icash_property_controls(account_id,property_id,manual) values(p_account,prop,p_action='takeover')
 on conflict(account_id,property_id) do update set manual=excluded.manual,updated_at=now();
 if p_action='return_to_bot' then
 update public.icash_handoffs set state='resolved',resolved_at=now() where account_id=p_account and screening_id=p_screening and state<>'resolved';
 -- Returning control never automatically retries a past callback.
 end if;
 else raise exception 'Invalid control';end if;
 insert into public.icash_control_events(account_id,actor_user_id,action,property_id) values(p_account,p_user,p_action,prop);
end $function$
